<script setup lang="ts">
import{computed,onMounted}from'vue';import{storeToRefs}from'pinia';import{RouterLink,useRoute}from'vue-router';import FinanceSubnav from'../components/FinanceSubnav.vue';import{useFinanceStore}from'../runtime/finance-store';import'./finance-views.css';import'./finance-receivable-views.css'
const store=useFinanceStore();const route=useRoute();const{receipts,writeoffs,loading,error}=storeToRefs(store);const row=computed(()=>receipts.value.find(v=>v.id===String(route.params.receiptId)));const related=computed(()=>writeoffs.value.filter(w=>w.allocations.some(a=>a.sourceKind==='receipt'&&a.sourceId===row.value?.id)));const money=(v:number)=>`¥${(v/100).toFixed(2)}`;onMounted(()=>Promise.all([store.loadReceipts(),store.loadWriteoffs()]))
</script>
<template><section class="finance-page"><header class="finance-header"><div><h1>收款单详情</h1><p>原单、账户流水、核销和作废审计均保留，不物理删除。</p></div></header><FinanceSubnav/><div v-if="error" class="finance-state error">{{error}}</div><div v-else-if="loading&&!row" class="finance-state">正在加载…</div><template v-else-if="row"><div class="finance-summary"><article><span>收款金额</span><strong>{{money(row.amountCents)}}</strong></article><article><span>已核销</span><strong class="fin-income">{{money(row.allocatedCents)}}</strong></article><article><span>可用预收</span><strong>{{money(row.availableCents)}}</strong></article><article><span>状态</span><strong>{{row.status==='normal'?'正常':'已作废'}}</strong></article></div><div class="finance-panel detail-grid"><div><span>收款单号</span><strong>{{row.receiptNo}}</strong></div><div><span>客户</span><strong>{{row.customerSnapshot.name}}</strong></div><div><span>收款日期</span><strong>{{row.occurredAt}}</strong></div><div><span>方式 / 账户</span><strong>{{row.method}} / {{row.accountId??'无资金账户'}}</strong></div><div><span>资金流水</span><strong>{{row.movementId??'余额方式不产生流水'}}</strong></div><div><span>凭证元数据</span><strong>{{row.attachment?.name??'—'}}</strong></div><div class="wide"><span>备注</span><strong>{{row.note??'—'}}</strong></div><div v-if="row.voidInfo" class="wide"><span>作废审计</span><strong>{{row.voidInfo.voidedAt}} · {{row.voidInfo.reason}} · 反向流水 {{row.voidInfo.reversalMovementId}}</strong></div></div><h2 class="section-title">核销记录</h2><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>核销单号</th><th>日期</th><th class="fin-money">现金</th><th class="fin-money">优惠</th><th>状态</th></tr></thead><tbody><tr v-for="item in related" :key="item.id"><td><RouterLink :to="`/finance/writeoffs/${item.id}`">{{item.writeoffNo}}</RouterLink></td><td>{{item.occurredAt}}</td><td class="fin-money">{{money(item.cashCents)}}</td><td class="fin-money">{{money(item.discountCents)}}</td><td>{{item.status==='active'?'有效':'已取消'}}</td></tr><tr v-if="!related.length"><td colspan="5">暂无核销记录</td></tr></tbody></table></div></template><div v-else class="finance-state">收款单不存在</div></section></template>
